alias Catering.Forms

# Let's create an order first
form = Forms.new_order_form()
form = Forms.add_nested(form, "order[line_items]", params: %{"dish" => "Pizza", "quantity" => 2})
form = Forms.add_nested(form, "order[line_items]", params: %{"dish" => "Burger", "quantity" => 1})
form = Forms.change(form, %{
  "reference" => "REF123",
  "line_items" => %{
    "0" => %{"dish" => "Pizza", "quantity" => "2"},
    "1" => %{"dish" => "Burger", "quantity" => "1"}
  }
})
{:ok, order} = Forms.save(form)

# Edit form
edit_form = Forms.edit_order_form(order.id)
# Reorder
edit_form = Forms.reorder(edit_form, "order[line_items]", [1, 0])

# Let's manually touch "line_items"
edit_form = %{edit_form | touched_forms: MapSet.put(edit_form.touched_forms, "line_items")}

IO.inspect(AshPhoenix.Form.params(edit_form))
